extends SceneTree

func _init():
	# Let's wait for one frame or do it in a deferred call
	call_deferred("run_test")

func run_test():
	print("Running deferred test...")
	var root_node = root
	var node = Node2D.new()
	root_node.add_child(node)

	# Initial state
	print("Initial pos: ", node.position)

	var tween = node.create_tween()
	tween.pause() # Pause so we can custom_step

	tween.tween_property(node, "position", Vector2(100, 100), 1.0).set_trans(Tween.TRANS_LINEAR)
	tween.tween_callback(func(): print("Step 1 done callback!"))

	print("Tween is valid: ", tween.is_valid())
	print("Tween is running: ", tween.is_running())

	for i in range(105):
		var active = tween.custom_step(0.01)
		if i % 10 == 0 or i == 99 or i == 104:
			print("Step %3d (t=%.2f): active=%s pos=%s" % [i, (i+1)*0.01, active, node.position])

	node.queue_free()
	quit()

extends SceneTree

func _init():
	call_deferred("run_verification")

func run_verification():
	var scene_path = "res://scenes/Animator.tscn"
	var scene = load(scene_path)
	var animator = scene.instantiate()
	root.add_child(animator)

	var target = animator.get_node("Target")
	var controller = animator.get_node("TweenController")

	var tween = controller.play_sequence()
	tween.pause()

	for i in range(110):
		tween.custom_step(0.01)
		var t = (i + 1) * 0.01
		print("Step %3d: t=%.2f, elapsed=%.6f, pos=%s" % [i, t, tween.get_total_elapsed_time(), target.position])

	animator.queue_free()
	quit()

